<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {ArrowRight,FileArchive,FileText,GitCompareArrows,LoaderCircle,RefreshCw,Search} from 'lucide-vue-next';
import type {ArchiveComparison} from '../../../../packages/shared/src/releases';
import {request,queryString} from '../api';
const props=defineProps<{base:string;branch:string;path?:string;baseRef?:string;headRef?:string}>();
const baseRevision=ref(props.baseRef??''),headRevision=ref(props.headRef??props.branch),basePath=ref(props.path??''),headPath=ref(props.path??'');
const comparison=ref<ArchiveComparison>(),loading=ref(false),reading=ref(false),error=ref(''),search=ref(''),showUnchanged=ref(false),selectedPath=ref('');
let generation=0,controller:AbortController|undefined;
const entries=computed(()=>comparison.value?.entries.filter(item=>(showUnchanged.value||item.status!=='unchanged'||item.metadataChanged)&&item.path.toLowerCase().includes(search.value.toLowerCase()))??[]);
const name=(status:string)=>({added:'新增',removed:'删除',modified:'修改',unchanged:'未变'}[status]??status);
const bytes=(size:number)=>size<1024?size+' B':size<1024*1024?(size/1024).toFixed(1)+' KiB':(size/1024/1024).toFixed(1)+' MiB';
async function load(entry?:string){const current=++generation;controller?.abort();controller=new AbortController();error.value='';if(entry)reading.value=true;else{loading.value=true;comparison.value=undefined;selectedPath.value='';}try{const previous=comparison.value;const result=await request<ArchiveComparison>(props.base+'/archive-diff'+queryString({baseRef:entry?previous!.baseCommitId:baseRevision.value,headRef:entry?previous!.headCommitId:headRevision.value,basePath:entry?previous!.basePath:basePath.value,headPath:entry?previous!.headPath:headPath.value,...(entry?{entry}:{})}),{signal:controller.signal});if(current!==generation)return;comparison.value=result;selectedPath.value=entry??'';}catch(cause){if(current===generation&&(cause as Error).name!=='AbortError')error.value=(cause as Error).message;}finally{if(current===generation){loading.value=false;reading.value=false;}}}
watch(()=>[props.base,props.branch,props.path,props.baseRef,props.headRef],()=>{++generation;controller?.abort();comparison.value=undefined;baseRevision.value=props.baseRef??'';headRevision.value=props.headRef??props.branch;basePath.value=props.path??'';headPath.value=props.path??'';error.value='';loading.value=false;reading.value=false;if(props.baseRef&&props.headRef&&props.path)void load();},{immediate:true});
watch(()=>[baseRevision.value,headRevision.value,basePath.value,headPath.value],()=>{++generation;controller?.abort();comparison.value=undefined;selectedPath.value='';error.value='';loading.value=false;reading.value=false;},{flush:'sync'});
onBeforeUnmount(()=>{++generation;controller?.abort();});
</script>
<template>
<section class="panel archive-comparison"><header class="panel-header"><div><h2><GitCompareArrows :size="19"/> ZIP 内容差异</h2><p>比较固定提交中的实际成员内容，不执行附件、不递归打开嵌套 ZIP。</p></div></header>
<form class="compare-form" @submit.prevent="load()"><label class="field">基准版本<input v-model="baseRevision" required placeholder="分支或提交 ID"/></label><label class="field">基准 ZIP 路径<input v-model="basePath" required placeholder="attachments/skill.zip"/></label><ArrowRight :size="16"/><label class="field">目标版本<input v-model="headRevision" required/></label><label class="field">目标 ZIP 路径<input v-model="headPath" required/></label><button class="btn btn-primary" :disabled="loading||reading"><LoaderCircle v-if="loading" class="spin" :size="15"/><GitCompareArrows v-else :size="15"/>比较</button></form>
<div v-if="error" class="error-state" role="alert">{{error}}<p>未完成比较；不能据此判断无差异。</p></div><div v-if="loading" class="empty" role="status"><LoaderCircle :size="25" class="spin"/>正在校验成员并计算 SHA-256…</div>
<template v-if="comparison"><div class="compare-summary"><strong>{{comparison.identicalBytes?'两个 ZIP 字节完全相同':comparison.contentEqual?'成员内容相同，ZIP 封装或元数据发生变化':'成员内容存在差异'}}</strong><span>新增 {{comparison.counts.added}} · 删除 {{comparison.counts.removed}} · 修改 {{comparison.counts.modified}} · 未变 {{comparison.counts.unchanged}}</span><code>{{comparison.baseCommitId.slice(0,10)}} → {{comparison.headCommitId.slice(0,10)}}</code></div><div class="compare-tools"><label class="search-field"><Search :size="14"/><input v-model="search" placeholder="搜索成员路径…" aria-label="搜索 ZIP 差异路径"/></label><label><input v-model="showUnchanged" type="checkbox"/>显示未变化成员</label></div>
<div class="compare-layout"><aside class="compare-members"><button v-for="item in entries" :key="item.path" :class="{active:selectedPath===item.path}" @click="load(item.path)"><FileArchive v-if="/\.zip$/i.test(item.path)" :size="15"/><FileText v-else :size="15"/><span><strong>{{item.path}}</strong><small>{{item.before?bytes(item.before.size):'—'}} → {{item.after?bytes(item.after.size):'—'}}<template v-if="item.renameHint"> · 疑似移动：{{item.renameHint}}</template><template v-if="item.metadataChanged"> · 权限/元数据变化</template></small></span><i :class="item.status">{{name(item.status)}}</i></button><p v-if="!entries.length" class="empty">没有匹配的成员变化。</p></aside>
<section class="compare-detail"><div v-if="reading" class="empty" role="status"><LoaderCircle :size="22" class="spin"/>正在载入固定版本差异…</div><template v-else-if="comparison.selected"><header><strong>{{comparison.selected.path}}</strong></header><div class="member-hashes"><p v-for="side in ['before','after'] as const" :key="side"><span>{{side==='before'?'基准 SHA-256':'目标 SHA-256'}}</span><code>{{comparison.entries.find(item=>item.path===selectedPath)?.[side]?.sha256??'该版本无此成员'}}</code></p></div><p v-if="comparison.selected.kind==='binary'" class="notice">{{comparison.selected.reason}}</p><p v-if="comparison.selected.kind==='text'&amp;&amp;comparison.selected.reason" class="notice">{{comparison.selected.reason}}</p><pre v-if="comparison.selected.kind==='text'" class="zip-diff-lines" tabindex="0" aria-label="成员逐行差异"><span v-for="(line,index) in comparison.selected.lines" :key="index" :class="line.type"><i>{{line.type==='added'?'+':line.type==='removed'?'-':' '}}</i>{{line.text}}
</span></pre></template><div v-else class="empty"><FileText :size="28"/><p>选择成员查看差异。小文本逐行展示，二进制与嵌套 ZIP 仅显示哈希。</p></div></section></div><footer class="compare-note">成员哈希比较已在容量限制内完成；这不构成恶意代码检测或安全证明。</footer></template></section>
</template>
<style scoped>
.archive-comparison h2{display:flex;gap:9px;align-items:center}.panel-header p{font-size:12px;color:var(--muted);margin-top:8px}.compare-form{display:grid;grid-template-columns:1fr 1.4fr 18px 1fr 1.4fr auto;gap:12px;align-items:end;padding:20px;border-bottom:1px solid var(--line)}.compare-form>.field{margin:0;min-width:0}.compare-form>svg{margin-bottom:12px;color:var(--muted)}.compare-form input{min-width:0;font-size:12px}.compare-summary{display:flex;gap:14px;flex-wrap:wrap;align-items:center;padding:17px 20px;border-bottom:1px solid var(--line);font-size:12px}.compare-summary strong{font-weight:500;color:var(--text)}.compare-summary span,.compare-summary code{color:var(--muted);font-size:11px}.compare-summary code{margin-left:auto}.compare-tools{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:14px 20px;font-size:12px;color:var(--muted);border-bottom:1px solid var(--line)}.compare-tools>.search-field{width:300px;max-width:60%}.compare-tools>label:last-child{display:flex;align-items:center;gap:7px}.compare-layout{display:grid;grid-template-columns:minmax(260px,35%) minmax(0,1fr);min-height:330px}.compare-members{border-right:1px solid var(--line);max-height:620px;overflow:auto;padding:8px;background:var(--bg)}.compare-members>button{width:100%;display:flex;align-items:start;gap:8px;padding:13px 10px;text-align:left;border:1px solid transparent;border-radius:5px;color:var(--text);font-size:12px}.compare-members>button:hover,.compare-members>button.active{background:var(--surface-raised);border-color:var(--line)}.compare-members>button>span{flex:1;min-width:0}.compare-members strong{display:block;overflow-wrap:anywhere;font-weight:500}.compare-members small{display:block;color:var(--muted);font-size:10px;margin-top:7px;line-height:1.7;overflow-wrap:anywhere}.compare-members i{font-style:normal;font-size:10px;color:var(--muted);white-space:nowrap}.compare-members .added{color:var(--success)}.compare-members .removed{color:var(--danger)}.compare-members .modified{color:var(--primary-hover)}.compare-detail{min-width:0}.compare-detail>header{padding:16px;border-bottom:1px solid var(--line);font-size:12px;overflow-wrap:anywhere}.member-hashes{padding:10px 16px;border-bottom:1px solid var(--line)}.member-hashes p{display:flex;gap:10px;align-items:start;font-size:10px;margin:5px 0}.member-hashes span{color:var(--muted);white-space:nowrap}.member-hashes code{overflow-wrap:anywhere;font-size:10px}.zip-diff-lines{margin:0;max-height:520px;overflow:auto;background:var(--bg);font:12px/1.8 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.zip-diff-lines>span{display:block;min-height:21px;padding:0 12px}.zip-diff-lines i{font-style:normal;display:inline-block;width:20px;user-select:none;color:var(--muted)}.zip-diff-lines .added{background:color-mix(in srgb,var(--success) 12%,transparent)}.zip-diff-lines .removed{background:color-mix(in srgb,var(--danger) 12%,transparent)}.compare-note{padding:13px 20px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.compare-detail>.notice{margin:16px}.error-state p{font-size:11px;margin-top:6px}@media(max-width:1000px){.compare-form{grid-template-columns:1fr 1.5fr}.compare-form>svg{display:none}.compare-form>.btn{grid-column:1/-1}.compare-layout{grid-template-columns:1fr}.compare-members{border-right:0;border-bottom:1px solid var(--line);max-height:260px}.compare-summary code{margin-left:0}}@media(max-width:600px){.compare-form{padding:15px;grid-template-columns:1fr}.compare-tools{padding:12px;flex-wrap:wrap}.compare-tools>.search-field{max-width:100%;width:100%}.compare-summary{padding:15px}.member-hashes p{flex-direction:column;gap:5px}}
</style>
